/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ApprovalIdentity, ApprovalChecklist, ApprovalMarks, ApprovalBody
 *   Functions: staleDecisions, staleDecisionEdits, shownDecisions, approvalTrackOrder, approvalChecklist,
 *              approvalBody
 * Internal
 *   Functions: identityOf
 *   Constants: notApplied
 * @end-catalog */

import type { DecisionEdits, ImportDecision, ImportDetail, ImportDraftV2 } from './adminApi';
import type { ImportCandidate } from './importIdentity';
import type { ImportDraftChange } from './importDraftPatch';

/**
 * One-step approval on the Web: the decisions a publication confirmation shows, its checklist of what becomes catalog content,
 * and the publish body bound to the saved project it was built on. Owner rules: docs/business-rules.md (Administrator Album Imports).
 */

/**
 * Whether buffered decisions were made for names the saved project no longer has: an Artist decision whose entry is gone or now
 * has another name, or a label decision whose label is gone or renamed. The server refuses those (ADMIN_IMPORT_DECISION_STALE).
 */
export function staleDecisions(item: ImportDetail, decisions: readonly ImportDecision[]): boolean {
  return decisions.some(decision => decision.scope === 'artist' ? item.draft.album.artists.find(entry => entry.key === decision.entryKey)?.name !== decision.boundName
    : decision.scope === 'label' && item.draft.album.label?.name !== decision.boundName);
}

/**
 * Whether a buffer of unsaved decisions is stale: made for a name since renamed (staleDecisions), or older than decisions another
 * save stored after it began (a decisions or approval receipt above its revision). The server refuses either.
 */
export function staleDecisionEdits(item: ImportDetail, edits: DecisionEdits): boolean {
  return staleDecisions(item, edits.decisions) || item.receipts.some(receipt => (receipt.kind === 'decisions' || receipt.kind === 'publish') && receipt.revision > edits.revision);
}

/**
 * Decisions the confirmation shows: unsaved Review edits, else the saved ones; null when the edits are stale (staleDecisionEdits;
 * Review then offers the saved decisions). Like the server's retainBoundDecisions, an Artist decision stays only while its
 * entry keeps its saved name in `draft`, a label decision only while both drafts name the same label, and an Album or track
 * decision only for an existing slot.
 */
export function shownDecisions(item: ImportDetail, draft: ImportDraftV2, edits: DecisionEdits | null): ImportDecision[] | null {
  if (edits && staleDecisionEdits(item, edits)) return null;
  const slots = new Set(item.draft.tracks.map(track => track.slotId)), savedLabel = item.draft.album.label?.name;
  return (edits?.decisions ?? item.decisions).filter(decision => {
    if (decision.scope === 'artist') {
      const saved = item.draft.album.artists.find(entry => entry.key === decision.entryKey);
      return Boolean(saved && draft.album.artists.some(entry => entry.key === saved.key && entry.name === saved.name));
    }
    if (decision.scope === 'label') return savedLabel !== undefined && draft.album.label?.name === savedLabel;
    return decision.scope === 'album' || slots.has(decision.slotId ?? '');
  });
}

/** Approved order: Disc Number (unknown counts as 1), then Track Number (unknown last), then draft order. */
export function approvalTrackOrder<T extends { discNumber: number | null; trackNumber: number | null }>(tracks: readonly T[]): T[] {
  const unknownLast = (left: number | null, right: number | null) => left === right ? 0 : left === null ? 1 : right === null ? -1 : left - right;
  return tracks.map((track, index) => ({ track, index }))
    .sort((left, right) => (left.track.discNumber ?? 1) - (right.track.discNumber ?? 1) || unknownLast(left.track.trackNumber, right.track.trackNumber) || left.index - right.index)
    .map(({ track }) => track);
}

/** What the confirmation says about one identity; needsDecision and changed block the approval. */
export type ApprovalIdentity = { kind: 'new' } | { kind: 'reused'; label: string; hidden: boolean } | { kind: 'needsDecision' } | { kind: 'changed' } | { kind: 'notApplied' };
export interface ApprovalChecklist {
  /** The Album decision reuses an existing Album: its values, entries, label and cover are not applied. */
  append: boolean;
  /** The Artist entries and the label rest only on file tags (automatic and not changed in this approval). */
  artistsFromTags: boolean; labelFromTags: boolean;
  artists: { key: string; name: string; role: 'primary' | 'featured'; joinPhrase: string | null; identity: ApprovalIdentity; possibleLabel: boolean }[];
  label: { name: string; identity: ApprovalIdentity } | null;
  album: ApprovalIdentity;
  /**
   * The tracks the approval adds in approved order, then the existing Album members it reuses in draft order (an append keeps a
   * member's stored title and position, so the draft's are not shown for it); skipped tracks are not catalog content and are left out.
   */
  tracks: { slotId: string; title: string; discNumber: number | null; trackNumber: number | null; existing: boolean; identity: ApprovalIdentity }[];
  blocked: number;
}
const notApplied: ApprovalIdentity = { kind: 'notApplied' };
/** A reuse is shown only while its candidate is listed at the reviewed revision; otherwise the match changed since review. */
const identityOf = (decision: ImportDecision | undefined, kind: ImportCandidate['kind'], candidates: readonly ImportCandidate[]): ApprovalIdentity => {
  if (decision?.action === 'create-distinct') return { kind: 'new' };
  if (decision?.action !== 'reuse') return { kind: 'needsDecision' };
  const candidate = candidates.find(item => item.kind === kind && item.id === decision.candidateId && item.revision === decision.candidateRevision);
  return candidate ? { kind: 'reused', label: candidate.label, hidden: candidate.visibility === 'hidden' } : { kind: 'changed' };
};
/** The saved project's automatic markers (`lookupPaths`: automatic values resting on applied metadata lookup) and the paths the approval's unsaved changes write. */
export interface ApprovalMarks { automaticPaths: readonly string[]; lookupPaths: readonly string[]; possibleLabelEntryKeys: readonly string[]; changedPaths: readonly string[] }
/**
 * The confirmation checklist of `draft` with the decisions it shows (shownDecisions) and the current duplicate candidates. A row
 * without an explicit decision reads its preselection (identityPreselections), so it is New or Reuses and blocks nothing; a row
 * neither answered nor preselected needs a decision. `marks` flag the Artist entries and the label that rest only on file tags
 * (automatic and not written by metadata lookup), and automatic entries named like a label; an append applies neither. A value the approval changes is the administrator's own,
 * and so are the label once it carries an explicit identity decision and the entries once any entry carries one (saved or
 * unsaved), so neither is marked then; a preselection never counts as one.
 */
export function approvalChecklist(draft: ImportDraftV2, decisions: readonly ImportDecision[], candidates: readonly ImportCandidate[], marks?: ApprovalMarks, preselections: readonly ImportDecision[] = []): ApprovalChecklist {
  const effective = (match: (decision: ImportDecision) => boolean) => decisions.find(match) ?? preselections.find(match);
  const albumDecision = effective(decision => decision.scope === 'album'), append = albumDecision?.action === 'reuse';
  const decided = (scope: 'artist' | 'label') => decisions.some(decision => decision.scope === scope && decision.action !== 'skip');
  const fromTags = (path: string) => !append && Boolean(marks?.automaticPaths.includes(path) && !marks.lookupPaths.includes(path) && !marks.changedPaths.includes(path));
  const artistsFromTags = fromTags('album.artists') && draft.album.artists.length > 0 && !decided('artist'), labelFromTags = fromTags('album.label') && draft.album.label !== null && !decided('label');
  const artists = draft.album.artists.map(({ key, name, role, joinPhrase }) => ({ key, name, role, joinPhrase, possibleLabel: artistsFromTags && Boolean(marks?.possibleLabelEntryKeys.includes(key)),
    identity: append ? notApplied : identityOf(effective(decision => decision.scope === 'artist' && decision.entryKey === key), 'artist', candidates) }));
  const label = draft.album.label && { name: draft.album.label.name, identity: append ? notApplied : identityOf(effective(decision => decision.scope === 'label'), 'organization', candidates) };
  const album = identityOf(albumDecision, 'album', candidates);
  const listed = draft.tracks.flatMap(({ slotId, title, discNumber, trackNumber }) => {
    const decision = effective(item => item.scope === 'track' && item.slotId === slotId);
    return decision?.action === 'skip' ? [] : [{ slotId, title, discNumber, trackNumber, existing: decision?.action === 'reuse', identity: identityOf(decision, 'track', candidates) }];
  });
  const tracks = [...approvalTrackOrder(listed.filter(track => !track.existing)), ...listed.filter(track => track.existing)];
  const blocked = [...artists.map(entry => entry.identity), ...(label ? [label.identity] : []), album, ...tracks.map(track => track.identity)]
    .filter(identity => identity.kind === 'needsDecision' || identity.kind === 'changed').length;
  return { append, artistsFromTags, labelFromTags, artists, label, album, tracks, blocked };
}

/** The publish body: the shown unsaved changes, decisions and saved cover, bound to the saved project by its approvalDigest. */
export function approvalBody(item: ImportDetail, changes: ImportDraftChange[], decisions: ImportDecision[]) {
  return { expectedRevision: item.revision, changes, decisions, selectedCoverSlotId: item.selectedCoverSlotId, approvalDigest: item.approvalDigest };
}
export type ApprovalBody = ReturnType<typeof approvalBody>;
